def parse_date(raw: str) -> date:
    """Read a Borough ``value_date`` field, which is an ISO date."""
    try:
        return datetime.strptime(raw.strip(), DATE_FORMAT).date()
    except ValueError as exc:
        raise LedgerParseError(f"Borough date {raw!r} is not a YYYY-MM-DD date") from exc


def parse_amount(raw: str) -> Decimal:
    """Read a Borough ``amount`` field as dollars; see :func:`to_major_units`."""
    return to_major_units(raw)


